// ElysiaPresence — ParticlesOrb aprovado (matemática original preservada, 720 partículas)
// + extensão de metamorfose: as mesmas partículas fluem para a silhueta humanoide.
// Em form = 0 o desenho é idêntico ao ParticlesOrb original (camada extra fica invisível e não é calculada).
const { useCallback, useEffect, useRef } = React;

const PARTICLE_COUNT = 720;
const EXTRA_COUNT = 18000; // detalhe exclusivamente humanoide; o orbe continua com 720 pontos
const TOTAL = PARTICLE_COUNT + EXTRA_COUNT;
const HEAD_VOLUME_COUNT = 4000;
const DRAW_CAPACITY = TOTAL + HEAD_VOLUME_COUNT;
const TWO_PI = Math.PI * 2;
const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));
const TIME_OFFSET = 1.7;
const TONE_BUCKETS = 6;
const ALPHA_BUCKETS = 10;
const BUCKETS = TONE_BUCKETS * ALPHA_BUCKETS;
const ANGLE_X = 0.32;
const ERROR_FROM_RGB = hexToRgb(ERROR_COLOR_FROM);
const ERROR_TO_RGB = hexToRgb(ERROR_COLOR_TO);
const FIG_ASPECT = 1024 / 1536;
// Uma única envoltória: crânio com nuca e a continuação da face/maxilar.
// Só suas partículas são desenhadas. As superfícies analíticas servem à oclusão.
const AVATAR_HEAD_SHAPES = [
  { x: 0, y: -0.377, z: -0.008, rx: 0.088, ry: 0.104, rz: 0.082 },
  { x: 0, y: -0.355, z: 0.028, rx: 0.068, ry: 0.083, rz: 0.044 },
];
const CHEST_Y = 0.06; // âncora (y normalizado) de onde a forma nasce
const FORM_IN_RATE = 1.35;
const FORM_OUT_RATE = 1.1;

const STATES = {
  idle: { tempo: 1, spin: 0.14, breathe: 0.05, drift: 1, ripple: 0, swell: 0.04, flow: 0, swirl: 0, pulse: 0, pulseRate: 1, ring: 0, jitter: 0, shake: 0, alpha: 0.72, rest: 0 },
  connecting: { tempo: 1, spin: 0.3, breathe: 0.02, drift: 0.2, ripple: 0, swell: 0, flow: 0, swirl: 0, pulse: 0.06, pulseRate: 0.5, ring: 1, jitter: 0, shake: 0, alpha: 0.8, rest: 0.12 },
  listening: { tempo: 1, spin: 0.55, breathe: 0.012, drift: 0, ripple: 1, swell: 0.12, flow: 0, swirl: 0, pulse: 0, pulseRate: 1, ring: 0, jitter: 0, shake: 0, alpha: 0.92, rest: 0.55 },
  thinking: { tempo: 1, spin: 0.32, breathe: 0.01, drift: 0, ripple: 0, swell: 0, flow: 0, swirl: 0, pulse: 1, pulseRate: 1, ring: 0, jitter: 0, shake: 0, alpha: 0.78, rest: 0.3 },
  speaking: { tempo: 1, spin: 0.24, breathe: 0.01, drift: 0, ripple: 0, swell: 0.06, flow: 1, swirl: 1, pulse: 0, pulseRate: 1, ring: 0, jitter: 0.6, shake: 0, alpha: 0.94, rest: 0.55 },
  error: { tempo: 1, spin: 0.08, breathe: 0, drift: 0, ripple: 0, swell: 0, flow: 0, swirl: 0, pulse: 0, pulseRate: 1, ring: 0, jitter: 0.7, shake: 1, alpha: 0.85, rest: 0.2 },
  disabled: { tempo: 0.04, spin: 0, breathe: 0, drift: 0, ripple: 0, swell: 0, flow: 0, swirl: 0, pulse: 0, pulseRate: 1, ring: 0, jitter: 0, shake: 0, alpha: 0.45, rest: 0 },
};

const buildSphere = (count) => {
  const s = {
    x: new Float32Array(count), y: new Float32Array(count), z: new Float32Array(count),
    ringFrac: new Float32Array(count), seed: new Float32Array(count),
    toneBucket: new Uint8Array(count), tone: new Float32Array(count),
  };
  for (let i = 0; i < count; i += 1) {
    const y = 1 - (i / (count - 1)) * 2;
    const radiusAtY = Math.sqrt(1 - y * y);
    const theta = GOLDEN_ANGLE * i;
    const tone = (i * 0.5436890126) % 1;
    s.x[i] = Math.cos(theta) * radiusAtY;
    s.y[i] = y;
    s.z[i] = Math.sin(theta) * radiusAtY;
    s.ringFrac[i] = (i * 0.61803398875) % 1;
    s.seed[i] = ((i * 0.7548776662) % 1) * TWO_PI;
    s.tone[i] = tone;
    s.toneBucket[i] = Math.min(TONE_BUCKETS - 1, Math.floor(tone * TONE_BUCKETS));
  }
  return s;
};

const SPHERE = buildSphere(PARTICLE_COUNT);
const EXTRA_SPHERE = buildSphere(EXTRA_COUNT);
const HEAD_SPHERE = buildSphere(HEAD_VOLUME_COUNT);

/* ---------- coordenadas de partículas extraídas da referência, não uma textura ---------- */
// Cada registro contém apenas u, v e luminosidade (3 inteiros de 16 bits).
// Não há imagem, vídeo, textura, malha de imagem ou drawImage na animação.
const AVATAR_PARTICLE_DATA = '';
let AVATAR = null;
let avatarPromise = null;

const mulberry = (a) => () => {
  a |= 0; a = (a + 0x6d2b79f5) | 0;
  let t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

// A projeção frontal aprovada é mantida. A profundidade só aparece ao girar:
// face/maxilar à frente do eixo do crânio e cabelo posterior atrás dele.
const avatarHeadWeight = (v) => {
  const t = clamp01((v - 0.225) / (0.295 - 0.225));
  return 1 - t * t * t * (t * (t * 6 - 15) + 10);
};

const avatarHeadFront = (nx, ny) => {
  let front = -Infinity;
  for (const shape of AVATAR_HEAD_SHAPES) {
    const section = 1 - ((nx - shape.x) / shape.rx) ** 2 - ((ny - shape.y) / shape.ry) ** 2;
    if (section >= 0) front = Math.max(front, shape.z + shape.rz * Math.sqrt(section));
  }
  return front;
};

const avatarHeadDepth = (nx, v) => {
  const surface = avatarHeadFront(nx, v - 0.5);
  const outerHair = -0.018 * Math.sqrt(Math.max(0, 1 - (nx / 0.145) ** 2));
  const neckBridge = 0.022 * Math.sqrt(Math.max(0, 1 - (nx / 0.050) ** 2));
  const frontZ = Number.isFinite(surface) ? surface : v > 0.218 && Math.abs(nx) < 0.050 ? neckBridge : outerHair;
  const bridge = 0.0035 * Math.exp(-((nx / 0.012) ** 2) - ((v - 0.146) / 0.024) ** 2);
  const headZ = frontZ + bridge;
  const neckWeight = smooth(clamp01((v - 0.225) / 0.025));
  const neckZ = 0.017 * Math.sqrt(Math.max(0, 1 - (nx / 0.036) ** 2));
  return headZ + (neckZ - headZ) * neckWeight;
};

// Só a superfície EXTERNA da união é amostrada: não há duas cabeças sobrepostas.
// Os detalhes vistos originalmente de frente permanecem nas partículas aprovadas.
const buildAvatarHeadVolume = (count) => {
  const x = new Float32Array(count), y = new Float32Array(count), z = new Float32Array(count);
  const nx = new Float32Array(count), ny = new Float32Array(count), nz = new Float32Array(count);
  const lum = new Float32Array(count), tone = new Uint8Array(count), hair = new Float32Array(count);
  const novelty = new Float32Array(count);
  const random = mulberry(918327);
  let i = 0;
  while (i < count) {
    const shapeIndex = random() < 0.78 ? 0 : 1;
    const shape = AVATAR_HEAD_SHAPES[shapeIndex];
    const sy = 1 - 2 * random(), radius = Math.sqrt(1 - sy * sy);
    const angle = random() * TWO_PI, sx = Math.cos(angle) * radius, sz = Math.sin(angle) * radius;
    const px = shape.x + sx * shape.rx, py = shape.y + sy * shape.ry, pz = shape.z + sz * shape.rz;
    let internal = false;
    for (let j = 0; j < AVATAR_HEAD_SHAPES.length; j += 1) {
      if (j === shapeIndex) continue;
      const other = AVATAR_HEAD_SHAPES[j];
      if (((px - other.x) / other.rx) ** 2 + ((py - other.y) / other.ry) ** 2 + ((pz - other.z) / other.rz) ** 2 < 1.00001) internal = true;
    }
    if (internal) continue;
    x[i] = px; y[i] = py; z[i] = pz;
    const length = Math.hypot(sx / shape.rx, sy / shape.ry, sz / shape.rz);
    nx[i] = sx / shape.rx / length; ny[i] = sy / shape.ry / length; nz[i] = sz / shape.rz / length;
    const faceOval = (px / 0.066) ** 2 + ((py + 0.5 - 0.145) / 0.080) ** 2;
    hair[i] = shapeIndex === 0 && (pz < 0.01 || faceOval > 1.10) ? 1 : 0;
    // Completa sobretudo os lados recém-revelados, não acende uma esfera inteira.
    novelty[i] = 1 - smooth(clamp01((nz[i] - 0.12) / 0.78));
    lum[i] = hair[i] ? 0.30 + random() * 0.32 : 0.18 + random() * 0.25;
    tone[i] = Math.min(TONE_BUCKETS - 1, Math.floor(random() * TONE_BUCKETS));
    i += 1;
  }
  return { x, y, z, nx, ny, nz, lum, tone, hair, novelty, ...buildAvatarBreathRig(x, y) };
};

// Máscara conservadora: mexe nas mechas externas, não na face, tronco ou braços.
const avatarHairWeight = (nx, v) => {
  if (v >= 0.62) return 0;
  const x = Math.abs(nx);
  const crown = 1 - smooth(clamp01((v - 0.055) / 0.035));
  const faceWidth = 0.066 * Math.sqrt(Math.max(0, 1 - ((v - 0.145) / 0.080) ** 2));
  const faceEdge = Math.max(0.048, faceWidth + 0.008);
  const shoulderEdge = 0.060 + 0.097 * smooth(clamp01((v - 0.225) / 0.075));
  const armEdge = 0.157 + Math.max(0, v - 0.30) * 0.22;
  const boundary = v < 0.225 ? faceEdge : v < 0.30 ? shoulderEdge : armEdge;
  const side = smooth(clamp01((x - boundary) / 0.016));
  const tips = 1 - smooth(clamp01((v - 0.55) / 0.07));
  return Math.max(crown, side) * tips;
};

const avatarBreathWeights = (nx, ny, chest) => {
  const v = ny + 0.5;
  const core = 1 - smooth(clamp01((Math.abs(nx) - 0.115) / 0.080));
  const torso = 1 - smooth(clamp01((v - 0.60) / 0.10));
  const belly = Math.exp(-(((v - 0.535) / 0.095) ** 2)) * core * torso;
  const shoulder = Math.exp(-(((v - 0.285) / 0.050) ** 2));
  const armFollow = smooth(clamp01((0.68 - v) / 0.36)) * (1 - core);
  const headLift = 1 - smooth(clamp01((v - 0.22) / 0.10));
  return {
    rib: nx * 0.013 * chest * core * torso,
    abdomen: nx * 0.004 * belly,
    rise: 0.0028 * chest * core * torso + 0.0007 * shoulder + 0.0012 * headLift + 0.0013 * armFollow,
  };
};

// Os pesos anatômicos são calculados uma única vez, nunca a cada quadro.
const buildAvatarBreathRig = (x, y, chest) => {
  const breathRib = new Float32Array(x.length), breathAbdomen = new Float32Array(x.length), breathRise = new Float32Array(x.length);
  for (let k = 0; k < x.length; k += 1) {
    const weights = avatarBreathWeights(x[k], y[k], chest ? chest[k] : 0);
    breathRib[k] = weights.rib; breathAbdomen[k] = weights.abdomen; breathRise[k] = weights.rise;
  }
  return { breathRib, breathAbdomen, breathRise };
};

const loadAvatarTargets = () => {
  if (avatarPromise) return avatarPromise;
  const binary = atob(AVATAR_PARTICLE_DATA);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  if (bytes.length !== TOTAL * 6) throw new Error('Dados de partículas do avatar inválidos');
  const packed = new DataView(bytes.buffer);
  const ax = new Float32Array(TOTAL), ay = new Float32Array(TOTAL), lum = new Float32Array(TOTAL);
  const delay = new Float32Array(TOTAL), sign = new Float32Array(TOTAL), tone = new Uint8Array(TOTAL);
  const head = new Float32Array(TOTAL), chest = new Float32Array(TOTAL), depth = new Float32Array(TOTAL);
  const hair = new Float32Array(TOTAL);
  const face = new Float32Array(TOTAL), normalX = new Float32Array(TOTAL), normalY = new Float32Array(TOTAL), normalZ = new Float32Array(TOTAL);
  const rand = mulberry(7);
  for (let k = 0; k < TOTAL; k += 1) {
    ax[k] = (packed.getUint16(k * 6, true) / 65535 - 0.5) * FIG_ASPECT;
    const v = packed.getUint16(k * 6 + 2, true) / 65535;
    ay[k] = v - 0.5;
    lum[k] = packed.getUint16(k * 6 + 4, true) / 65535;
    tone[k] = Math.min(TONE_BUCKETS - 1, Math.floor(rand() * TONE_BUCKETS));
    const d = Math.hypot(ax[k] * 1.1, ay[k] - CHEST_Y);
    delay[k] = clamp01((d / 0.62) * 0.7 + rand() * 0.3);
    sign[k] = rand() < 0.5 ? -1 : 1;
    head[k] = avatarHeadWeight(v);
    chest[k] = Math.exp(-Math.pow((v - 0.415) / 0.145, 2));
    depth[k] = avatarHeadDepth(ax[k], v);
    hair[k] = avatarHairWeight(ax[k], v);
    const fx = ax[k] / 0.066, fy = (v - 0.145) / 0.080;
    const faceOval = fx * fx + fy * fy;
    face[k] = (1 - smooth(clamp01((faceOval - 0.95) / 0.65))) * (1 - smooth(clamp01((v - 0.215) / 0.02)));
    const fz = Math.sqrt(Math.max(0, 1 - faceOval)), length = Math.hypot(fx, fy, fz) || 1;
    normalX[k] = fx / length; normalY[k] = fy / length; normalZ[k] = fz / length;
  }
  AVATAR = { ax, ay, lum, delay, sign, tone, head, chest, depth, hair, face, normalX, normalY, normalZ,
    ...buildAvatarBreathRig(ax, ay, chest),
    headVolume: buildAvatarHeadVolume(HEAD_VOLUME_COUNT) };
  avatarPromise = Promise.resolve(AVATAR);
  return avatarPromise;
};

const smooth = (x) => x * x * (3 - 2 * x);

const createAvatarMotion = () => ({
  random: mulberry(230519), time: 0,
  lookX: 0, lookY: 0, tilt: 0, targetX: 0, targetY: 0, targetTilt: 0,
  pointerX: 0, pointerY: 0, yaw: 0, pitch: 0, roll: 0, breath: 0, sway: 0,
  cosYaw: 1, sinYaw: 0, cosPitch: 1, cosRoll: 1, sinRoll: 0, sinPitch: 0,
  yawVelocity: 0, pitchVelocity: 0, rollVelocity: 0, attention: 0,
  neckYaw: 0, neckPitch: 0, neckRoll: 0,
  neckYawVelocity: 0, neckPitchVelocity: 0, neckRollVelocity: 0,
  breathBelly: 0, hairYaw: 0, hairPitch: 0, hairYawVelocity: 0, hairPitchVelocity: 0, hairStrength: 0,
  cosNeckYaw: 1, sinNeckYaw: 0, cosNeckPitch: 1, sinNeckPitch: 0, cosNeckRoll: 1, sinNeckRoll: 0,
  gaze: { start: 0, duration: 1.2, next: 0.9, fromX: 0, fromY: 0, fromTilt: 0 },
});

// Trajetória com velocidade e aceleração nulas nas extremidades de cada olhar.
// Não interfere no smooth() original usado na metamorfose das partículas.
const easeAvatarGaze = (t) => t * t * t * (t * (t * 6 - 15) + 10);

// Mola criticamente amortecida: preserva a inércia ao mudar de direção e não oscila.
const stepAvatarHead = (m, axis, velocityKey, target, omega, maxSpeed, dt) => {
  if (dt <= 0) return;
  const current = m[axis], velocity = m[velocityKey];
  const error = current - target, decay = Math.exp(-omega * dt);
  const travel = (velocity + omega * error) * dt;
  let next = target + (error + travel) * decay;
  let nextVelocity = (velocity - omega * travel) * decay;
  const maxStep = maxSpeed * dt;
  if (Math.abs(next - current) > maxStep) {
    next = current + Math.sign(next - current) * maxStep;
    nextVelocity = Math.sign(nextVelocity) * Math.min(maxSpeed, Math.abs(nextVelocity));
  }
  m[axis] = next;
  m[velocityKey] = nextVelocity;
};

// Inspiração mais curta, expiração longa e uma pausa suave no repouso.
// O movimento não segue a voz e não escala o corpo inteiro como um balão.
const avatarBreathCycle = (phase) => {
  const p = ((phase % 1) + 1) % 1;
  if (p < 0.37) return easeAvatarGaze(p / 0.37);
  if (p < 0.93) return 1 - easeAvatarGaze((p - 0.37) / 0.56);
  return 0;
};

const updateAvatarMotion = (m, dt, pointer, reduced) => {
  if (reduced) {
    m.yaw = m.pitch = m.roll = m.breath = m.sway = 0;
    m.cosYaw = m.cosPitch = m.cosRoll = 1; m.sinYaw = m.sinRoll = m.sinPitch = 0;
    m.yawVelocity = m.pitchVelocity = m.rollVelocity = 0;
    m.neckYaw = m.neckPitch = m.neckRoll = 0;
    m.neckYawVelocity = m.neckPitchVelocity = m.neckRollVelocity = 0;
    m.cosNeckYaw = m.cosNeckPitch = m.cosNeckRoll = 1;
    m.sinNeckYaw = m.sinNeckPitch = m.sinNeckRoll = 0;
    m.pointerX = m.pointerY = m.attention = 0;
    m.breathBelly = m.hairYaw = m.hairPitch = m.hairYawVelocity = m.hairPitchVelocity = m.hairStrength = 0;
    return m;
  }
  m.time += dt;
  const gaze = m.gaze;
  if (m.time >= gaze.next) {
    gaze.fromX = m.lookX; gaze.fromY = m.lookY; gaze.fromTilt = m.tilt;
    gaze.start = gaze.next;
    const returnToFront = m.random() < 0.22;
    const amplitude = returnToFront ? 0.02 + m.random() * 0.035 : 0.15 + m.random() * 0.25;
    m.targetX = (m.random() < 0.5 ? -1 : 1) * amplitude;
    m.targetY = (m.random() * 2 - 1) * 0.050;
    m.targetTilt = -m.targetX * 0.025 + (m.random() * 2 - 1) * 0.006;
    // Alterna olhares breves, movimentos mais demorados e momentos de repouso.
    gaze.duration = 0.95 + m.random() * 1.25;
    const hold = 0.75 + m.random() * 2.25;
    gaze.next = gaze.start + gaze.duration + hold;
  }
  const progress = easeAvatarGaze(clamp01((m.time - gaze.start) / gaze.duration));
  m.lookX = gaze.fromX + (m.targetX - gaze.fromX) * progress;
  m.lookY = gaze.fromY + (m.targetY - gaze.fromY) * progress;
  m.tilt = gaze.fromTilt + (m.targetTilt - gaze.fromTilt) * progress;

  // Atenção gradual ao cursor; sair da janela não estala a cabeça para o centro.
  m.attention = approach(m.attention, pointer.active ? 1 : 0, pointer.active ? 4.2 : 2.1, dt);
  const px = pointer.active ? Math.max(-1, Math.min(1, pointer.x)) : 0;
  const py = pointer.active ? Math.max(-1, Math.min(1, pointer.y)) : 0;
  m.pointerX = approach(m.pointerX, Math.abs(px - m.pointerX) < 0.004 ? m.pointerX : px, 6.5, dt);
  m.pointerY = approach(m.pointerY, Math.abs(py - m.pointerY) < 0.004 ? m.pointerY : py, 6.0, dt);
  const cursorX = Math.tanh(m.pointerX * 1.08) / Math.tanh(1.08);
  const cursorY = Math.tanh(m.pointerY * 1.08) / Math.tanh(1.08);
  const wandering = 1 - 0.75 * m.attention;

  // Variações pequenas e contínuas, sem vibração ou ciclo curto de "sim/não".
  const t = m.time;
  const microYaw = 0.0028 * (Math.sin(t * 0.83) + 0.38 * (Math.sin(t * 1.47 + 0.7) - Math.sin(0.7)));
  const microPitch = 0.0021 * (Math.sin(t * 0.67) + 0.30 * (Math.sin(t * 1.19 + 1.1) - Math.sin(1.1)));
  const microRoll = 0.0014 * (Math.sin(t * 0.53) + 0.24 * (Math.sin(t * 1.03 + 0.4) - Math.sin(0.4)));
  // O gesto principal é virar o rosto em Y (até cerca de 41 graus), não tombá-lo.
  const yawTarget = m.lookX * wandering + cursorX * 0.620 * m.attention + microYaw;
  const pitchTarget = m.lookY * wandering + cursorY * 0.100 * m.attention + microPitch;
  stepAvatarHead(m, 'yaw', 'yawVelocity', yawTarget, 6.5 + 3.0 * m.attention, 0.90, dt);
  stepAvatarHead(m, 'pitch', 'pitchVelocity', pitchTarget, 5.4 + 2.3 * m.attention, 0.45, dt);
  // A inclinação acompanha o giro com um pequeno atraso e depois se acomoda.
  const rollTarget = m.tilt * wandering + m.yaw * 0.012 - m.yawVelocity * 0.006 + microRoll * 0.6;
  stepAvatarHead(m, 'roll', 'rollVelocity', rollTarget, 4.8 + 1.3 * m.attention, 0.12, dt);
  // Articulação separada: o pescoço apenas acompanha, com amplitude pequena e atraso.
  stepAvatarHead(m, 'neckYaw', 'neckYawVelocity', m.yaw * 0.075 + microYaw * 0.3, 3.6, 0.08, dt);
  stepAvatarHead(m, 'neckPitch', 'neckPitchVelocity', m.pitch * 0.08, 3.2, 0.04, dt);
  stepAvatarHead(m, 'neckRoll', 'neckRollVelocity', m.roll * 0.12 + microRoll * 0.4, 2.8, 0.025, dt);
  const breathPhase = m.time / 5.1 + 0.012 * Math.sin(m.time * 0.18);
  const breathDepth = 0.94 + 0.06 * Math.sin(m.time * 0.23 + 0.20);
  m.breath = avatarBreathCycle(breathPhase) * breathDepth;
  m.breathBelly = avatarBreathCycle(breathPhase + 0.025) * breathDepth;
  // A raiz permanece presa à cabeça; a extensão das mechas recebe a inércia.
  stepAvatarHead(m, 'hairYaw', 'hairYawVelocity', m.yaw + m.neckYaw, 3.1, 0.80, dt);
  stepAvatarHead(m, 'hairPitch', 'hairPitchVelocity', m.pitch + m.neckPitch, 2.8, 0.30, dt);
  m.hairStrength = 1 - Math.exp(-m.time * 1.8);
  m.sway = Math.sin(m.time * 0.48) * 0.0014;
  m.cosYaw = Math.cos(m.yaw); m.sinYaw = Math.sin(m.yaw);
  m.cosPitch = Math.cos(m.pitch); m.sinPitch = Math.sin(m.pitch);
  m.cosRoll = Math.cos(m.roll); m.sinRoll = Math.sin(m.roll);
  m.cosNeckYaw = Math.cos(m.neckYaw); m.sinNeckYaw = Math.sin(m.neckYaw);
  m.cosNeckPitch = Math.cos(m.neckPitch); m.sinNeckPitch = Math.sin(m.neckPitch);
  m.cosNeckRoll = Math.cos(m.neckRoll); m.sinNeckRoll = Math.sin(m.neckRoll);
  return m;
};

// Rotação rígida XYZ em torno do centro do crânio, seguida da articulação cervical.
// A profundidade nunca é uma textura: são coordenadas das próprias partículas.
const rotateAvatarHeadPoint = (nx, ny, nz, m, out) => {
  if (m.yaw === 0 && m.pitch === 0 && m.roll === 0 && m.neckYaw === 0 && m.neckPitch === 0 && m.neckRoll === 0) {
    out.x = nx; out.y = ny; out.z = nz;
    return out;
  }
  const headCenterY = -0.355, neckPivotY = -0.235;
  const dy = ny - headCenterY;
  const x1 = nx * m.cosYaw + nz * m.sinYaw;
  const z1 = -nx * m.sinYaw + nz * m.cosYaw;
  const y1 = dy * m.cosPitch - z1 * m.sinPitch;
  const z2 = dy * m.sinPitch + z1 * m.cosPitch;
  const x2 = x1 * m.cosRoll - y1 * m.sinRoll;
  const y2 = headCenterY + x1 * m.sinRoll + y1 * m.cosRoll;
  const nx1 = x2 * m.cosNeckYaw + z2 * m.sinNeckYaw;
  const nz1 = -x2 * m.sinNeckYaw + z2 * m.cosNeckYaw;
  const ny1 = (y2 - neckPivotY) * m.cosNeckPitch - nz1 * m.sinNeckPitch;
  const nz2 = (y2 - neckPivotY) * m.sinNeckPitch + nz1 * m.cosNeckPitch;
  out.x = nx1 * m.cosNeckRoll - ny1 * m.sinNeckRoll;
  out.y = neckPivotY + nx1 * m.sinNeckRoll + ny1 * m.cosNeckRoll;
  out.z = nz2;
  return out;
};

const avatarHeadFacing = (nx, ny, nz, m) => {
  const x1 = nx * m.cosYaw + nz * m.sinYaw;
  const z1 = -nx * m.sinYaw + nz * m.cosYaw;
  const y1 = ny * m.cosPitch - z1 * m.sinPitch;
  const z2 = ny * m.sinPitch + z1 * m.cosPitch;
  const x2 = x1 * m.cosRoll - y1 * m.sinRoll;
  const y2 = x1 * m.sinRoll + y1 * m.cosRoll;
  const z3 = -x2 * m.sinNeckYaw + z2 * m.cosNeckYaw;
  return y2 * m.sinNeckPitch + z3 * m.cosNeckPitch;
};

const deformAvatarParticle = (nx, ny, head, chest, depth, m, out, rig, k = 0) => {
  const v = ny + 0.5;
  if (head > 0) rotateAvatarHeadPoint(nx, ny, depth, m, out);
  else { out.x = nx; out.y = ny; }
  const hx = out.x, hy = out.y;
  const weights = rig ? null : avatarBreathWeights(nx, ny, chest);
  const rib = rig ? rig.breathRib[k] : weights.rib;
  const abdomen = rig ? rig.breathAbdomen[k] : weights.abdomen;
  const rise = rig ? rig.breathRise[k] : weights.rise;
  out.x = nx + (hx - nx) * head
    + m.breath * rib + m.breathBelly * abdomen
    + m.sway * (1 - v);
  out.y = ny + (hy - ny) * head
    - m.breath * rise;
  return out;
};

const deformAvatarHair = (nx, ny, weight, m, out) => {
  if (weight <= 0 || m.hairStrength <= 0) return out;
  const length = clamp01((ny + 0.5 - 0.055) / 0.55);
  const loose = length * length * weight * m.hairStrength;
  const side = nx < 0 ? -1 : 1;
  const phase = m.time * 0.85 - length * 3.0 + side * 0.60 + nx * 2;
  const breeze = 0.0025 * Math.sin(phase) + 0.0009 * Math.sin(m.time * 1.43 - length * 4.1 + side);
  const inertia = Math.tanh((m.hairYaw - m.yaw - m.neckYaw) * 2.2) * 0.0048 - m.hairYaw * 0.0035;
  out.x += loose * (breeze + inertia);
  out.y += loose * (0.0009 * Math.sin(phase - 0.7) + (m.hairPitch - m.pitch - m.neckPitch) * 0.018);
  return out;
};

// Proxies numéricos de profundidade; não desenham malha, textura ou imagem.
// A interseção analítica do raio com a envoltória oculta a superfície distante.
const updateAvatarHeadOccluders = (m, occluders) => {
  const origin = {}, ex = {}, ey = {}, ez = {};
  rotateAvatarHeadPoint(0, -0.355, 0, m, origin);
  rotateAvatarHeadPoint(1, -0.355, 0, m, ex);
  rotateAvatarHeadPoint(0, 0.645, 0, m, ey);
  rotateAvatarHeadPoint(0, -0.355, 1, m, ez);
  for (const axis of ['x', 'y', 'z']) { ex[axis] -= origin[axis]; ey[axis] -= origin[axis]; ez[axis] -= origin[axis]; }
  for (let i = 0; i < AVATAR_HEAD_SHAPES.length; i += 1) {
    const s = AVATAR_HEAD_SHAPES[i], q = occluders[i];
    deformAvatarParticle(s.x, s.y, 1, 0, s.z, m, q);
    const a = 1 / (s.rx * s.rx), b = 1 / (s.ry * s.ry), c = 1 / (s.rz * s.rz);
    q.xx = ex.x * ex.x * a + ey.x * ey.x * b + ez.x * ez.x * c;
    q.yy = ex.y * ex.y * a + ey.y * ey.y * b + ez.y * ez.y * c;
    q.zz = ex.z * ex.z * a + ey.z * ey.z * b + ez.z * ez.z * c;
    q.xy = ex.x * ex.y * a + ey.x * ey.y * b + ez.x * ez.y * c;
    q.xz = ex.x * ex.z * a + ey.x * ey.z * b + ez.x * ez.z * c;
    q.yz = ex.y * ex.z * a + ey.y * ey.z * b + ez.y * ez.z * c;
  }
  return occluders;
};

const avatarHeadVisibility = (x, y, z, occluders) => {
  let front = -Infinity;
  for (const q of occluders) {
    const dx = x - q.x, dy = y - q.y;
    const b = q.xz * dx + q.yz * dy;
    const c = q.xx * dx * dx + 2 * q.xy * dx * dy + q.yy * dy * dy - 1;
    const discriminant = b * b - q.zz * c;
    if (discriminant >= 0) front = Math.max(front, q.z + (-b + Math.sqrt(discriminant)) / q.zz);
  }
  return 1 - smooth(clamp01((front - z - 0.0015) / 0.0035));
};

const ElysiaPresence = ({
  state = 'idle',
  size = 212,
  speed = 1,
  colorFrom = '#8b5cf6',
  colorTo = '#d946ef',
  levelRef,
  form = 0,            // alvo de forma: 0 = orbe, 1 = humanoide
  width,               // largura do canvas (área de desenho, não escala)
  height,              // altura do canvas
  avatarSrc = 'assets/avatar-ref.png',
  onForm,              // callback com o progresso real da forma (0..1)
  label = 'Elysia',
  className,
}) => {
  const hostRef = useRef(null);
  const canvasRef = useRef(null);
  const pointerRef = useRef({ x: 0, y: 0, active: false });
  const headMotionRef = useRef(null);
  const colorRef = useRef({ from: colorFrom, to: colorTo });
  const drawRef = useRef(null);
  const formTargetRef = useRef(form);
  const formRef = useRef(form);
  const onFormRef = useRef(onForm);
  const cw = Math.max(width || size, size);
  const ch = Math.max(height || size, size);

  useEffect(() => { onFormRef.current = onForm; }, [onForm]);
  useEffect(() => { loadAvatarTargets(avatarSrc); }, [avatarSrc]);

  useEffect(() => {
    const onMove = (event) => {
      if (event.pointerType === 'touch') return;
      const rect = hostRef.current?.getBoundingClientRect();
      if (!rect || !rect.width || !rect.height) return;
      pointerRef.current = {
        x: Math.max(-1, Math.min(1, (event.clientX - rect.left) / rect.width * 2 - 1)),
        y: Math.max(-1, Math.min(1, (event.clientY - rect.top) / rect.height * 2 - 1)),
        active: true,
      };
    };
    const onLeave = (event) => { if (!event.relatedTarget) pointerRef.current.active = false; };
    const onBlur = () => { pointerRef.current.active = false; };
    window.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('pointerout', onLeave);
    window.addEventListener('blur', onBlur);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerout', onLeave);
      window.removeEventListener('blur', onBlur);
    };
  }, []);

  const onFrame = useCallback((frame) => drawRef.current?.(frame), []);
  const { frameRef } = useOrbAnimator(hostRef, { state, levelRef, speed, onFrame });

  useEffect(() => {
    formTargetRef.current = form;
    if (prefersReducedMotion()) formRef.current = form;
    drawRef.current?.({ ...frameRef.current, dt: 0 });
  }, [form, frameRef]);

  useEffect(() => {
    colorRef.current = { from: colorFrom, to: colorTo };
    drawRef.current?.({ ...frameRef.current, dt: 0 });
  }, [colorFrom, colorTo, frameRef]);

  useEffect(() => {
    const host = hostRef.current;
    const canvas = canvasRef.current;
    if (!host || !canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = cw * dpr;
    canvas.height = ch * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // geometria original do orbe (relativa a `size`), deslocada para o centro do canvas
    const center = size / 2;
    const ocx = cw / 2;
    const ocy = ch / 2;
    const smallness = Math.min(1, size / 140);
    const dotScale = 0.55 + 0.45 * smallness;
    const alphaScale = smallness * smallness;
    const baseRadius = center * 0.62;

    // geometria da silhueta
    const figH = Math.min(ch * 0.97, (cw * 0.98) / FIG_ASPECT);
    const figScale = Math.max(0.55, Math.min(1.25, figH / 640));

    const px = new Float32Array(DRAW_CAPACITY), py = new Float32Array(DRAW_CAPACITY), pr = new Float32Array(DRAW_CAPACITY);
    const bucketOf = new Uint8Array(DRAW_CAPACITY);
    const order = new Uint16Array(DRAW_CAPACITY);
    const counts = new Uint16Array(BUCKETS);
    const starts = new Uint16Array(BUCKETS);
    const toneStyles = new Array(TONE_BUCKETS).fill('#fff');

    let paletteKey = '';
    let lastPhase = frameRef.current.phase;
    let lastLevelText = '';
    let lastFormReport = -1;
    let clock = 0, pulseClock = 0, angleY = 0, ringPhase = 0, avClock = 0;
    const avatarMotion = headMotionRef.current || (headMotionRef.current = createAvatarMotion());
    const headOccluders = AVATAR_HEAD_SHAPES.map(() => ({}));
    const avatarDotScale = Math.sqrt(9000 / EXTRA_COUNT);

    const ensurePalette = (errorW) => {
      const { from, to } = colorRef.current;
      const errKey = Math.round(errorW * 64);
      const key = `${from}|${to}|${errKey}`;
      if (key === paletteKey) return;
      paletteKey = key;
      const e = errKey / 64;
      const f = mixRgb(hexToRgb(from), ERROR_FROM_RGB, e);
      const t = mixRgb(hexToRgb(to), ERROR_TO_RGB, e);
      for (let b = 0; b < TONE_BUCKETS; b += 1) toneStyles[b] = rgba(mixRgb(f, t, (b + 0.5) / TONE_BUCKETS), 1);
    };

    const draw = (frame) => {
      const w = frame.weights;
      const p = blendStates(w, STATES);
      const dPhase = Math.max(0, frame.phase - lastPhase);
      lastPhase = frame.phase;
      const level = frame.reduced ? p.rest : frame.level;
      const levelText = frame.level.toFixed(3);
      if (levelText !== lastLevelText) { lastLevelText = levelText; host.style.setProperty('--orb-level', levelText); }

      // progresso da metamorfose (independente da velocidade do orbe, para nunca "travar" no meio)
      const ft = AVATAR ? formTargetRef.current : 0;
      if (frame.reduced) formRef.current = ft;
      else formRef.current = approach(formRef.current, ft, ft > formRef.current ? FORM_IN_RATE : FORM_OUT_RATE, frame.dt || 0);
      if (Math.abs(formRef.current - ft) < 0.0008) formRef.current = ft;
      const F = formRef.current;
      const fr = Math.round(F * 100) / 100;
      if (fr !== lastFormReport) { lastFormReport = fr; onFormRef.current?.(fr); host.style.setProperty('--form', fr); }

      clock += dPhase * p.tempo;
      pulseClock += dPhase * p.tempo * p.pulseRate;
      angleY += dPhase * p.spin * (1 + p.ripple * level * 1.8);
      ringPhase = (ringPhase + dPhase * 0.7) % TWO_PI;
      avClock += frame.reduced ? 0 : (frame.dt || 0);
      const t = clock + TIME_OFFSET;
      const pt = pulseClock + TIME_OFFSET;

      const beat = Math.sin(pt * 2.6) * 0.5 + 0.5;
      const beatSharp = beat * beat * beat;
      const breathe = p.breathe * Math.sin(t * 1.1);
      const conv = p.pulse * (0.06 + 0.12 * beatSharp);
      const radius = baseRadius * (1 + breathe + level * p.swell - conv);

      const shakeAmp = p.shake * radius * 0.05;
      const shakeX = shakeAmp * (Math.sin(t * 26) + 0.5 * Math.sin(t * 15.7));
      const shakeY = shakeAmp * (Math.cos(t * 22.5) + 0.5 * Math.sin(t * 13.1));

      const driftAmp = p.drift * radius * 0.055;
      const jitterAmp = p.jitter * radius * (0.012 + level * 0.07);
      const rippleAmp = p.ripple * (0.04 + level * 0.22);
      const pulseAmp = p.pulse * 0.16 * (0.4 + 0.6 * beat);
      const flowAmp = p.flow * (0.18 + level * 0.4);
      const swirlAmp = p.swirl * (0.35 + level * 0.9);
      const ringW = clamp01(p.ring);
      const ringBreath = 1 + p.pulse * 0.4 * Math.sin(pt * 2.6);

      const cosX = Math.cos(ANGLE_X);
      const sinX = Math.sin(ANGLE_X);
      counts.fill(0);

      // parâmetros vivos da silhueta
      const at = avClock;
      const avEnergy = clamp01(level * 1.6);
      const morphing = F > 0.0005 && AVATAR;
      const A = AVATAR;
      const motion = updateAvatarMotion(avatarMotion, morphing ? (frame.dt || 0) : 0,
        pointerRef.current, frame.reduced || frame.state === 'disabled');
      const faceTurn = smooth(clamp01((Math.hypot(motion.yaw + motion.neckYaw, (motion.pitch + motion.neckPitch) * 0.65) - 0.015) / 0.16));
      if (morphing && faceTurn > 0) updateAvatarHeadOccluders(motion, headOccluders);

      const avatarPoint = (k, seed, out) => {
        const ny = A.ay[k];
        const nx = A.ax[k];
        deformAvatarParticle(nx, ny, A.head[k], A.chest[k], A.depth[k], motion, out, A, k);
        const visibility = faceTurn > 0 && ny < -0.275
          ? 1 - faceTurn * (1 - avatarHeadVisibility(out.x, out.y, out.z, headOccluders)) : 1;
        deformAvatarHair(nx, ny, A.hair[k], motion, out);
        // Movimento individual dos pontos, sem qualquer camada de imagem.
        const microHair = clamp01((Math.abs(nx) - 0.12) * 4) * clamp01((0.15 - ny) * 3);
        const flowX = microHair * 0.7 * figScale * Math.sin(at * 1.4 + ny * 9 + seed);
        const jit = (0.15 + avEnergy * 0.3) * figScale;
        out.x = ocx + out.x * figH + flowX + jit * Math.sin(at * 3.1 + seed * 7.3);
        out.y = ocy + out.y * figH + jit * Math.cos(at * 2.7 + seed * 5.1);
        // onda de energia subindo pelo corpo enquanto ela fala
        const waveB = 0.5 + 0.5 * Math.sin(ny * 11 + at * 4.2);
        const twinkle = 0.78 + 0.22 * Math.sin(at * 2.3 + seed * 11);
        const l = A.lum[k];
        out.a = clamp01((0.2 + 0.85 * l) * twinkle * (0.82 + 0.4 * avEnergy * waveB)) * visibility;
        out.d = (0.45 + l * 1.25) * figScale * avatarDotScale * Math.sqrt(visibility);
      };
      const ap = { x: 0, y: 0, a: 0, d: 0 };

      for (let i = 0; i < PARTICLE_COUNT; i += 1) {
        const sx = SPHERE.x[i];
        const sy = SPHERE.y[i];
        const sz = SPHERE.z[i];
        const seed = SPHERE.seed[i];
        const ringFrac = SPHERE.ringFrac[i];

        const twist = swirlAmp > 0.002 ? angleY + swirlAmp * Math.sin(sy * 2.4 + t * 1.6) : angleY;
        const cy = Math.cos(twist);
        const sny = Math.sin(twist);
        const x1 = sx * cy - sz * sny;
        const z1 = sx * sny + sz * cy;
        const y1 = sy * cosX - z1 * sinX;
        const z2 = sy * sinX + z1 * cosX;

        const depth = (z2 + 1) / 2;
        const perspective = 0.65 + depth * 0.45;

        let pointRadius = radius;
        if (rippleAmp > 0.002) pointRadius *= 1 + rippleAmp * (0.5 + 0.5 * Math.sin(sy * 4.5 - t * 6.5));
        if (pulseAmp > 0.002) pointRadius *= 1 - pulseAmp * (0.5 + 0.5 * Math.sin(ringFrac * TWO_PI + pt * 3.1));
        if (flowAmp > 0.002) {
          const stream = 0.5 + 0.5 * Math.sin(seed * 3 - t * 3.4);
          pointRadius *= 1 - flowAmp * stream * stream;
        }

        let ox = shakeX;
        let oy = shakeY;
        if (driftAmp > 0.01) {
          ox += driftAmp * (Math.sin(t * 0.55 + seed * 3.7) + 0.5 * Math.sin(t * 1.3 + seed * 1.3));
          oy += driftAmp * (Math.cos(t * 0.62 + seed * 2.9) + 0.5 * Math.sin(t * 1.05 + seed * 5.1));
        }
        if (jitterAmp > 0.01) {
          ox += jitterAmp * Math.sin(t * 14 + seed * 9.3);
          oy += jitterAmp * Math.cos(t * 17 + seed * 6.1);
        }

        let screenX = ocx + x1 * pointRadius * perspective + ox;
        let screenY = ocy + y1 * pointRadius * perspective + oy;
        let alpha = 0.12 + depth * depth * 0.78;
        let dot = 0.6 + depth * 1.5;

        if (ringW > 0.004) {
          const tone = SPHERE.tone[i];
          const ringAngle = (i / PARTICLE_COUNT) * TWO_PI + ringPhase + 0.05 * Math.sin(t * 1.3 + seed);
          const ringR = center * (0.58 + 0.13 * ringFrac) * (1 + 0.05 * Math.sin(t + seed * 1.7)) * ringBreath;
          const circleX = ocx + Math.cos(ringAngle) * ringR;
          const circleY = ocy + Math.sin(ringAngle) * ringR;
          screenX += (circleX - screenX) * ringW;
          screenY += (circleY - screenY) * ringW;
          alpha += (0.35 + tone * 0.5 - alpha) * ringW;
          dot += (0.75 + tone * 0.9 - dot) * ringW;
        }

        dot *= dotScale;
        alpha *= alphaScale;

        if (morphing) {
          const m = smooth(clamp01(F * 1.7 - A.delay[i] * 0.7));
          if (m > 0) {
            avatarPoint(i, seed, ap);
            const dx = ap.x - screenX, dy = ap.y - screenY;
            const arc = Math.sin(m * Math.PI) * 0.22 * A.sign[i];
            screenX += dx * m - dy * arc;
            screenY += dy * m + dx * arc;
            alpha += (ap.a - alpha) * m;
            dot += (ap.d - dot) * m;
          }
        }

        px[i] = screenX;
        py[i] = screenY;
        pr[i] = dot;
        const ab = Math.min(ALPHA_BUCKETS - 1, Math.floor(alpha * ALPHA_BUCKETS));
        const b = SPHERE.toneBucket[i] * ALPHA_BUCKETS + ab;
        bucketOf[i] = b;
        counts[b] += 1;
      }

      // camada de detalhe: nasce de dentro do orbe e só aparece durante a forma humanoide
      let drawn = PARTICLE_COUNT;
      if (morphing) {
        const cyA = Math.cos(angleY), syA = Math.sin(angleY);
        for (let j = 0; j < EXTRA_COUNT; j += 1) {
          const k = PARTICLE_COUNT + j;
          const m = smooth(clamp01(F * 1.7 - A.delay[k] * 0.7));
          if (m <= 0.01) continue;
          const sx = EXTRA_SPHERE.x[j], sy = EXTRA_SPHERE.y[j], sz = EXTRA_SPHERE.z[j];
          const seed = EXTRA_SPHERE.seed[j];
          const x1 = sx * cyA - sz * syA;
          const z1 = sx * syA + sz * cyA;
          const y1 = sy * cosX - z1 * sinX;
          const r = radius * (0.35 + 0.6 * EXTRA_SPHERE.ringFrac[j]);
          const startX = ocx + x1 * r, startY = ocy + y1 * r;
          avatarPoint(k, seed, ap);
          if (ap.a <= 0.003) continue;
          const dx = ap.x - startX, dy = ap.y - startY;
          const arc = Math.sin(m * Math.PI) * 0.18 * A.sign[k];
          px[drawn] = startX + dx * m - dy * arc;
          py[drawn] = startY + dy * m + dx * arc;
          pr[drawn] = ap.d * 0.78;
          const alpha = ap.a * 0.85 * m;
          const ab = Math.min(ALPHA_BUCKETS - 1, Math.floor(alpha * ALPHA_BUCKETS));
          const b = A.tone[k] * ALPHA_BUCKETS + ab;
          bucketOf[drawn] = b;
          counts[b] += 1;
          drawn += 1;
        }
        if (faceTurn > 0) {
          const volume = A.headVolume;
          const m = smooth(clamp01(F * 1.7 - 0.24));
          for (let j = 0; j < HEAD_VOLUME_COUNT; j += 1) {
            const facing = avatarHeadFacing(volume.nx[j], volume.ny[j], volume.nz[j], motion);
            if (facing <= -0.015 || volume.novelty[j] <= 0.002) continue;
            deformAvatarParticle(volume.x[j], volume.y[j], 1, 0, volume.z[j], motion, ap, volume, j);
            const visibility = avatarHeadVisibility(ap.x, ap.y, ap.z, headOccluders)
              * smooth(clamp01((facing + 0.015) / 0.28));
            const seed = HEAD_SPHERE.seed[j];
            const alpha = (0.24 + volume.lum[j] * 0.60) * visibility * volume.novelty[j] * faceTurn * m
              * (0.88 + 0.12 * Math.sin(at * 2.1 + seed * 11));
            if (alpha <= 0.012) continue;
            deformAvatarHair(volume.x[j], volume.y[j], volume.hair[j], motion, ap);
            const targetX = ocx + ap.x * figH, targetY = ocy + ap.y * figH;
            const sx = HEAD_SPHERE.x[j], sy = HEAD_SPHERE.y[j], sz = HEAD_SPHERE.z[j];
            const x1 = sx * cyA - sz * syA, z1 = sx * syA + sz * cyA;
            const startX = ocx + x1 * radius * 0.5, startY = ocy + (sy * cosX - z1 * sinX) * radius * 0.5;
            px[drawn] = startX + (targetX - startX) * m;
            py[drawn] = startY + (targetY - startY) * m;
            pr[drawn] = (0.44 + volume.lum[j] * 0.76) * figScale * avatarDotScale * Math.sqrt(faceTurn * visibility);
            const ab = Math.min(ALPHA_BUCKETS - 1, Math.floor(alpha * ALPHA_BUCKETS));
            const b = volume.tone[j] * ALPHA_BUCKETS + ab;
            bucketOf[drawn] = b; counts[b] += 1; drawn += 1;
          }
        }
      }

      let acc = 0;
      for (let b = 0; b < BUCKETS; b += 1) { starts[b] = acc; acc += counts[b]; }
      for (let i = 0; i < drawn; i += 1) { const b = bucketOf[i]; order[starts[b]] = i; starts[b] += 1; }

      ensurePalette(w.error);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, cw, ch);
      ctx.globalCompositeOperation = 'lighter';

      let cursor = 0;
      for (let b = 0; b < BUCKETS; b += 1) {
        const count = counts[b];
        if (count === 0) continue;
        const ab = b % ALPHA_BUCKETS;
        ctx.globalAlpha = clamp01(((ab + 0.5) / ALPHA_BUCKETS) * p.alpha);
        ctx.fillStyle = toneStyles[(b - ab) / ALPHA_BUCKETS];
        ctx.beginPath();
        for (let k = cursor; k < cursor + count; k += 1) {
          const i = order[k];
          if (i < PARTICLE_COUNT) {
            // Os 720 pontos do orbe mantêm o desenho original, inclusive em transição.
            ctx.moveTo(px[i] + pr[i], py[i]);
            ctx.arc(px[i], py[i], pr[i], 0, TWO_PI);
          } else {
            // Micro-pontos subpixel: evita construir milhares de arcos por quadro.
            // São primitivas de partículas, não pixels de imagem ou sprites.
            const d = pr[i] * 1.55;
            ctx.fillRect(px[i] - d / 2, py[i] - d / 2, d, d);
          }
        }
        ctx.fill();
        cursor += count;
      }
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
    };

    drawRef.current = draw;
    draw({ ...frameRef.current, dt: 0 });
    return () => { drawRef.current = null; };
  }, [size, cw, ch, frameRef]);

  return (
    <div
      ref={hostRef}
      role="img"
      aria-label={label}
      data-state={state}
      className={className}
      style={{
        ...orbVars({ size, speed, colorFrom, colorTo }),
        width: cw,
        height: ch,
        display: 'grid',
        placeItems: 'center',
        opacity: state === 'disabled' ? 0.5 : 1,
        filter: state === 'disabled' ? 'grayscale(0.85)' : 'grayscale(0)',
        transition: 'opacity 0.4s ease, filter 0.4s ease',
      }}
    >
      <canvas ref={canvasRef} style={{ width: cw, height: ch }} />
    </div>
  );
};

Object.assign(window, { ElysiaPresence, loadAvatarTargets });
